const <oap:target id="auth-middleware-name">verifyAuthToken</oap:target> = (<oap:target id="auth-req-param">req</oap:target>, <oap:target id="auth-res-param">res</oap:target>, <oap:target id="auth-next-param">next</oap:target>) => {
  const <oap:target id="auth-header-name">authHeader</oap:target> = <oap:target id="auth-req-headers-access">req.headers['authorization']</oap:target>;
  const <oap:target id="auth-api-key-name">apiKey</oap:target> = req.headers['x-api-key'];
  const <oap:target id="auth-token-prefix">tokenPrefix</oap:target> = '<oap:target id="auth-bearer-prefix">Bearer </oap:target>';
  const <oap:target id="expected-token">expectedToken</oap:target> = <oap:target id="expected-token-value">secrettoken</oap:target>;
  const <oap:target id="expected-api-key">expectedApiKey</oap:target> = 'secrettoken';

  const <oap:target id="auth-bearer-valid-check">bearerValid</oap:target> = <oap:target id="auth-header-present-check">authHeader</oap:target> && <oap:target id="auth-header-prefix-check">authHeader.startsWith(tokenPrefix)</oap:target> && <oap:target id="auth-token-match-check">authHeader.slice(tokenPrefix.length) === expectedToken</oap:target>;
  const <oap:target id="auth-api-key-valid-check">apiKeyValid</oap:target> = typeof apiKey === 'string' && apiKey === expectedApiKey;

  if (!<oap:target id="auth-bearer-valid-check-2">bearerValid</oap:target> && !<oap:target id="auth-api-key-valid-check-2">apiKeyValid</oap:target>) {
    return <oap:target id="auth-missing-return">res.status(401).json({ message: 'Missing or invalid authorization token' })</oap:target>;
  }

  <oap:target id="auth-next-call">next()</oap:target>;
};
